fn is_prime(n: i8) -> bool {
    // Numbers less than 2 are not prime
    if n < 2 {
        return false;
    }
    
    // Check divisibility by numbers from 2 to n-1
    let mut divisor = 2;
    
    // Loop invariant: divisor is in [2, n]
    // Termination measure: n - divisor (strictly decreases each iteration)
    while divisor < n {
        if n % divisor == 0 {
            return false;  // Found a divisor, not prime
        }
        divisor += 1;
    }
    
    // No divisors found, number is prime
    true
}